INSERT INTO `testimonials` (`id`, `client_name`, `client_title`, `location`, `review`, `rating`, `client_avatar`, `verified_buyer`, `created_at`) VALUES (1, 'Vikramaditya Singhania', 'Managing Partner, Private Equity', 'Worli, Mumbai', 'EstateVista India transformed what is typically an opaque transaction into a discreet, highly curated private advisory experience. Their access to off-market sea-view penthouses in South Mumbai is unmatched.', 5, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80', 1, '2026-11-04 00:11:01');
INSERT INTO `testimonials` (`id`, `client_name`, `client_title`, `location`, `review`, `rating`, `client_avatar`, `verified_buyer`, `created_at`) VALUES (2, 'Rohit & Natasha Goel', 'Founders, Tech Enterprises', 'Golf Course Rd, Gurugram', 'Finding a residence with championship golf frontage and biometric private elevator access was seamless. EstateVista orchestrated private viewings, legal due diligence, and registration with supreme discretion.', 5, 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80', 1, '2026-11-04 00:11:01');
INSERT INTO `testimonials` (`id`, `client_name`, `client_title`, `location`, `review`, `rating`, `client_avatar`, `verified_buyer`, `created_at`) VALUES (3, 'Sunil Mehta', 'Global Design Director', 'Assagao, Goa', 'The level of market intelligence, structural verification, and RERA transparency provided by EstateVista sets the gold standard for luxury property advisory across India.', 5, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80', 1, '2026-11-04 00:11:01');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `author_id`, `author`, `read_time`, `publish_date`, `image_url`, `excerpt`, `content`, `status`, `views_count`, `created_at`, `updated_at`) VALUES (1, 'The Rise of Branded Residences: Why India\'s Billionaires Are Paying a 40% Premium', 'the-rise-of-branded-residences-in-india', 'Market Intelligence', 1, 'EstateVista Research Desk', '5 min read', 'November 2026', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1200&q=80', 'An in-depth analysis of how partnerships with luxury hospitality brands like Armani/Casa, Four Seasons, and Trump Towers are redefining prime real estate values in Mumbai and Delhi NCR.', '<p>Over the past three years, branded residences have outpaced standard luxury apartments by over 38% in capital appreciation across South Mumbai and Central Delhi. Ultra-high-net-worth individuals prioritize international hotel-grade concierge services, private biometric security, and pre-vetted peer communities.</p><h3>Key Investment Drivers</h3><p>According to EstateVista Private Wealth Research, key catalysts include bespoke interior appointments, globally recognized title clearance, and steady rental yields from multinational diplomats and executives.</p>', 'published', 1840, '2026-11-05 01:00:48', '2026-11-07 12:06:48');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `author_id`, `author`, `read_time`, `publish_date`, `image_url`, `excerpt`, `content`, `status`, `views_count`, `created_at`, `updated_at`) VALUES (2, 'RERA Due Diligence for High-Value Transactions: The Essential 7-Point Checklist', 'rera-due-diligence-luxury-real-estate-checklist', 'Legal & Advisory', 2, 'Meera Nambiar (Legal)', '7 min read', 'October 2026', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80', 'Essential title verification protocols, encumbrance certificates, and RERA compliance standards required before executing multi-crore real estate acquisitions.', '<p>Navigating luxury real estate in India requires sophisticated due diligence beyond basic registry searches. Our advisory legal desk outlines the non-negotiable verifications for high-value acquisitions.</p><h3>1. Title Search Period</h3><p>Ensure an uninterrupted 30-year title lineage verified through government sub-registrar records and public gazette notices.</p>', 'published', 2410, '2026-11-05 01:00:48', '2026-11-07 12:06:48');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `author_id`, `author`, `read_time`, `publish_date`, `image_url`, `excerpt`, `content`, `status`, `views_count`, `created_at`, `updated_at`) VALUES (3, 'Ultra-Luxury Coastal Estates: The North Goa Luxury Corridor Boom', 'north-goa-luxury-corridor-boom', 'Lifestyle & Estates', 3, 'Ananya Goenka', '4 min read', 'September 2026', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=80', 'Why Silicon Valley and Mumbai tech founders are driving record sales in Assagao, Candolim, and Moira heritage villa corridors.', '<p>Goa has evolved from a seasonal vacation destination into a permanent second-home sanctuary for India\'s startup founders and venture capitalists. Architectural villas combining heritage Portuguese facades with Scandinavian interiors command the highest demand.</p>', 'published', 1620, '2026-11-05 01:00:48', '2026-11-07 12:06:48');
